    def calculate(self, data: StockDataInfo, for_date: datetime.date) -> float:
        closes = data.filter_close_dates_until(for_date)
        _, middle, _ = talib.BBANDS(np.array(closes))
        return middle[-1]


class BbLower(IStockIndicator):
    @staticmethod
    def id():
        return "BB_Lower"

    def calculate(self, data: StockDataInfo, for_date: datetime.date) -> float:
        closes = data.filter_close_dates_until(for_date)
        _, _, lower = talib.BBANDS(np.array(closes))
        return lower[-1]


class SoSlowK(IStockIndicator):
    @staticmethod
    def id():
        return "SO_SlowK"

    def calculate(self, data: StockDataInfo, for_date: datetime.date) -> float:
        high_prices = data.filter_high_dates_until(for_date)
        low_prices = data.filter_low_dates_until(for_date)
        closes = data.filter_close_dates_until(for_date)
        slowk, _ = talib.STOCH(np.array(high_prices),
                               np.array(low_prices),
                               np.array(closes))
        return slowk[-1]


class SoSlowD(IStockIndicator):
    @staticmethod
    def id():
        return "SO_SlowD"

    def calculate(self, data: StockDataInfo, for_date: datetime.date) -> float:
        high_prices = data.filter_high_dates_until(for_date)
        low_prices = data.filter_low_dates_until(for_date)
        closes = data.filter_close_dates_until(for_date)
        _, slowd = talib.STOCH(np.array(high_prices), np.array(low_prices), np.array(closes))

        return slowd[-1]


class ADX(IStockIndicator):
    @staticmethod
    def id():
        return "ADX"

    def calculate(self, data: StockDataInfo, for_date: datetime.date) -> float:
        high_prices = data.filter_high_dates_until(for_date)
        low_prices = data.filter_low_dates_until(for_date)
        closes = data.filter_close_dates_until(for_date)

        return talib.ADX(np.array(high_prices), np.array(low_prices), np.array(closes))[-1]


class AroonOscillator(IStockIndicator):
    @staticmethod
    def id():
        return "Aroon_Oscillator"

    def calculate(self, data: StockDataInfo, for_date: datetime.date) -> float:
        high_prices = data.filter_high_dates_until(for_date)
        low_prices = data.filter_low_dates_until(for_date)
        aroon_up, aroon_down = talib.AROON(np.array(high_prices), np.array(low_prices))
        aroon_oscillator = aroon_up - aroon_down

        return aroon_oscillator[-1]


class OBV(IStockIndicator):
    @staticmethod
    def id():
        return "OBV"

    def calculate(self, data: StockDataInfo, for_date: datetime.date) -> float:
        closes = data.filter_close_dates_until(for_date)
        volumes = data.filter_volumes_dates_until(for_date)
        return talib.OBV(np.array(closes, dtype=np.float64),
                         np.array(volumes, dtype=np.float64))[-1]

from pymonad.either import Either as __pyEither
from typing import Any, Generic, TypeVar


"""
# Aided with basic GitHub coding tools

This module extends the functionality of the `pymonad.either.Either` class by adding additional
methods and shorthand operators for improved usability.

Classes:
    Either: A subclass of `pymonad.either.Either` that provides additional methods and operator overloads.

Functions:
    Left(value: M) -> Either[M, Any]:
        Creates a value of the first possible type in the Either monad, representing a failure or error state.

    Right(value: T) -> Either[Any, T]:
        Creates a value of the second possible type in the Either monad, representing a success state.

Type Variables:
    M: Represents the type of the value in the `Left` state (typically used for error messages or failure values).
    S: Unused in this module but reserved for potential future extensions.
    T: Represents the type of the value in the `Right` state (typically used for success values).
"""


M = TypeVar('M')
S = TypeVar('S')
T = TypeVar('T')


class Either(__pyEither, Generic[M, T]):
    """Extend pymonad Either"""

    def __rshift__(self, func):
        """Use `>>` as a shorthand for `bind`"""
        return self.bind(func)

    def __or__(self, func):
        """Use `|` as a shorthand for `bind`"""
        return self.bind(func)

    def then(self, func):
        """Use `then` as a shorthand for `bind`"""
        return self.bind(func)

    @property
    def error(self) -> str | None:
        """when the instance is a Left, can use `l.error` to get the error message"""
        if self.is_left():
            return self.monoid[0]
        return None


def Left(value: M) -> Either[M, Any]:
    """Creates a value of the first possible type in the Either monad."""
    return Either(None, (value, False))


def Right(value: T) -> Either[Any, T]:
    """Creates a value of the second possible type in the Either monad."""
    return Either(value, (None, True))

import functools
import json
import sys
from statistics import mean

from parser_utils import Parser, NoQuestionFound, AAID_REGEX, FIND_DIGIT_REGEX


class InvalidURLException(BaseException):
    def __init__(self, url, *args):
        self.__url = url
        super().__init__(*args)

    def __str__(self):
        return f"Invalid URL {self.__url}"


def catch(func):
    @functools.wraps(func)
    def stub(self, *args, **kwargs):
        try:
            return func(self, *args, *kwargs)
        except NoQuestionFound:  # raised in parser, questions finished
            return True, True
        except KeyboardInterrupt:
            sys.exit()  # quits script
        except BaseException as e:
            return None, e

    return stub


class AnswerHandler:
    """
    handles all the answer logic
    """

    def __init__(self, session):
        self.sesh = session
        self.headers = {'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko)'
                                      ' Chrome/71.0.3578.98 Safari/537.36'}
        self.process_ans_url = 'https://www.drfrostmaths.com/homework/process-answer.php'
        self.answer_functions = {'expression': self.answer_expression,
                                 'numeric': self.answer_numeric,
                                 'eqnsolutions': self.answer_eqnsolutions,
                                 'coordinate': self.answer_coordinate,
                                 'multiplechoice': self.answer_multiplechoice,
                                 'textual': self.answer_textual,
                                 'fraction': self.answer_fraction,
                                 'vector': self.answer_vector,
                                 'table': self.answer_table,
                                 'shape': self.answer_shape,
                                 'list': self.answer_list,
                                 'standardform': self.answer_standardform}

    @catch
    def answer_questions(self, url: str):
        """
        main loop answers questions util an error is raised
        due to no more questions, invalid input or connection errors.

        Decorator handles returns.

        Answer process:

        - Post deliberately wrong answer without aaid i.e. {'qid': 1228, 'qnum': 1, 'expression-answer-1': 1}.
        - Sever sends correct answer without registering an attempt as no aaid was associated with the request.
        - Parse response for answer, use appropriate function.
        - Send answer with aaid i.e. {'qid': 1228, 'qnum': 1, 'expression-answer-1': "parsed answer", aaid: 12848}.
        - question answered!

        repeat.
        """

        try:
            aaid = FIND_DIGIT_REGEX.findall(AAID_REGEX.findall(url)[0])[0]
        except IndexError:
            raise InvalidURLException(url)

        while True:  # main loop
            # remove &qnum=NUMBER in case already appended
            page = self.sesh.get("".join(url.split("&qnum=")[:1]), headers=self.headers).text  # get question page
            data, type_ = Parser.parse(page)  # parse question data
            answer = self.find_answer(data, type_)  # retrieve answer to question
            data['aaid'] = aaid
            try:
                result = self.answer_functions[type_](data, answer)  # select appropriate function to process answer
            except KeyError:
                self.new_type(answer, type_)  # not implemented type
                continue  # skips auto submit

            self.submit(result)

    def find_answer(self, data: dict, type_: str):
        """
        Attempts to find the correct answer to the current question.

        :param data: request payload
        :param type_: answer type
        :return: correct answer string
        """
        data = dict(data)
        data[f'{type_}-answer-1'] = '1'  # prepare incorrect  answer
        print(f'Question number: {data["qnum"]}', '|', f'Question type: {type_}')
        r = self.sesh.post(self.process_ans_url, data=data, headers=self.headers)  # submit incorrect answer
        _json = json.loads(r.text)
        return _json['answer']  # parse correct answer

    def submit(self, data: dict):
        # noinspection PyBroadException
        try:
            r = self.sesh.post(self.process_ans_url, data=data, timeout=3)
        except BaseException:
            return False

        _json = json.loads(r.text)
        if not _json['isCorrect']:
            self.wrong_answer(_json, data)
            return False
        return True

    @staticmethod
    def new_type(answer: dict, type_: str):
        print(f'No system in place to auto submit this answer type ({type_}) yet you will have to type it in manually:'
              f'\n {answer}')
        input('Press enter to proceed: ')

    @staticmethod
    def wrong_answer(response, data: dict):
        print('-- The wrong answer was submitted --')
        print('The following data if for debugging:')
        print(f'Request: {data}')
        print(f'Response: {response}')

    # answer specific functions --:

    @staticmethod
    def answer_expression(data, answer):
        answer = [answer['main']]
        data['expression-answer'] = answer
        return data

    @staticmethod
    def answer_numeric(data, answer):
        for index, item in enumerate(answer):
            if item['exact']:
                data[f'numeric-answer-{index + 1}'] = item['exact']
            else:
                # find mid value
                data[f'numeric-answer-{index + 1}'] = mean([float(item["to"]), float(item["from"])])
        return data

    @staticmethod
    def answer_eqnsolutions(data, answer):
        data['eqnsolutions-answer'] = str(answer).replace("'", '"').replace(' ', '')
        return data

    @staticmethod
    def answer_coordinate(data, answer):
        data['expression-answer-x'] = answer['x']
        data['expression-answer-y'] = answer['y']
        return data

    @staticmethod
    def answer_multiplechoice(data, answer):
        data['multiplechoice-answer[]'] = answer
        return data

    @staticmethod
    def answer_textual(data, answer):
        for index, item in enumerate(answer):
            data[f'textual-answer-{index + 1}'] = item
        return data

    @staticmethod
    def answer_fraction(data, answer):
        data['fraction-numer'] = answer['numer']
        data['fraction-denom'] = answer['denom']
        return data

    @staticmethod
    def answer_vector(data, answer):
        data['expression-answer-vector'] = str(answer).replace("'", '"')
        return data

    @staticmethod
    def answer_table(data, answer):
        for z, i in enumerate(answer):
            for p, x in enumerate(i):
                if x:
                    data[f'table-answer-{z + 1}-{p + 1}'] = x
        data['expression-answer-table'] = str(answer).replace("'", '"')
        return data

    @staticmethod
    def answer_shape(data, answer):
        data['shape-answer'] = str(answer).replace("'", '"').replace(' ', '')
        return data

    @staticmethod
    def answer_list(data, answer):
        ans = ','.join(answer)
        data['list-answer'] = ans
        return data

    @staticmethod
    def answer_standardform(data, answer):
        data['expression-answer-main'] = answer['main']
        data['expression-answer-power'] = answer['power']
        return data

class Node:

    def __init__(self, data):

        self.left = None
        self.right = None
        self.data = data
# Insert Node
    def insert(self, data):

        if self.data:
            if data < self.data:
                if self.left is None:
                    self.left = Node(data)
                else:
                    self.left.insert(data)
            elif data > self.data:
                if self.right is None:
                    self.right = Node(data)
                else:
                    self.right.insert(data)
        else:
            self.data = data

# Print the Tree
    def PrintTree(self):
        if self.left:
            self.left.PrintTree()
        print( self.data),
        if self.right:
            self.right.PrintTree()

# Inorder traversal
# Left -> Root -> Right
    def inorderTraversal(self, root):
        res = []
        if root:
            res = self.inorderTraversal(root.left)
            res.append(root.data)
            res = res + self.inorderTraversal(root.right)
        return res

root = Node(27)
root.insert(14)
root.insert(35)
root.insert(10)
root.insert(19)
root.insert(31)
root.insert(42)
print(root.inorderTraversal(root))

import os
import sys
import subprocess

project_path = os.path.join(os.path.dirname(__file__), 'vibora')

# Seeking for files pending compilation.
pending_compilation = set()
for root, dirs, files in os.walk(project_path):
    for file in files:
        if file.endswith('.pyx'):
            pending_compilation.add(os.path.join(root, file))
        elif file.endswith('.py'):
            if (file[:-3] + '.pxd') in files:
                pending_compilation.add(os.path.join(root, file))
        elif file.endswith(('.so', '.c', '.html')):
            os.remove(os.path.join(root, file))

# Calling Cython to compile our extensions.
cython = os.path.join(os.path.dirname(sys.executable), 'cython')
process = subprocess.run([cython] + list(pending_compilation) + ['--fast-fail'])
if process.returncode != 0:
    raise SystemExit(f'Failed to compile .pyx files to C.')

# Building native extensions.
process = subprocess.run(
    [
        sys.executable,
        os.path.join(os.path.dirname(project_path), 'setup.py'),
        'build_ext',
        '--inplace'
    ]
)
if process.returncode != 0:
    raise SystemExit(f'Failed to build native modules.')

print('Build process completed successfully.')

#!/usr/bin/python
# -*- coding: UTF-8 -*-
import re
import time
from datetime import timedelta, timezone, datetime
from random import randint
from re import Pattern

from requests import session, Response, Session

from notifier import Notifier

shanghai_tz = timezone(timedelta(hours=8), name='Asia/Shanghai')


def get_current_hour() -> int:
    now = datetime.utcnow().replace(tzinfo=timezone.utc)
    return now.astimezone(shanghai_tz).hour


class Job:
    _login_header: dict = {
        'Content-Type': 'application/x-www-form-urlencoded',
        'Host': 'pass.neu.edu.cn',
        'Origin': 'https://pass.neu.edu.cn',
    }

    _init_url: str = 'https://e-report.neu.edu.cn/login'

    _service_url: str = 'https://e-report.neu.edu.cn/notes/create'

    _update_info_url: str = 'https://e-report.neu.edu.cn/api/notes'

    _feedback_url: str = "https://e-report.neu.edu.cn/notes"

    _lt_matcher: Pattern = re.compile(r'name="lt" value="(.+?)"')

    _login_path_matcher: Pattern = re.compile(r'id="loginForm" action="(.+?)"')

    _token_matcher: Pattern = re.compile(r'name="_token" value="(.+?)"')

    _name_matcher: Pattern = re.compile(r'当前用户：(.+?) <span')

    _class_matcher: Pattern = re.compile(r'"suoshubanji":"(.+?)"')

    _date_matcher: Pattern = re.compile(r'"created_on":"(.+?)"')

    _wrong_auth: str = '账号或密码错误'
    _bad_info: str = '信息获取失败'
    _bad_init_login: str = '获取登陆信息失败'

    def __init__(self, username: str, password: str, ip: str = ''):
        self._username: str = username
        self._password: str = password
        self._ip: str = ip
        self._client: Session = session()

        # 获取到的跨步骤共用中间信息
        self._token: str = ""
        self._name: str = ""
        self._lt = ""
        self._login_path: str = ""
        self._class: str = ""
        self._date: str = ""

    @property
    def _login_body(self) -> str:
        return f'rsa={self._username}{self._password}{self._lt}&ul={len(self._username)}&pl={len(self._password)}&lt={self._lt}&execution=e1s1&_eventId=submit'

    @property
    def _login_url(self) -> str:
        return f'https://pass.neu.edu.cn{self._login_path}'

    @property
    def _update_info_body(self) -> str:
        return f'_token={self._token}&jibenxinxi_shifoubenrenshangbao=1&profile%5Bxuegonghao%5D={self._username}&profile%5Bsuoshubanji%5D={self._class}&jiankangxinxi_muqianshentizhuangkuang=%E6%AD%A3%E5%B8%B8&xingchengxinxi_weizhishifouyoubianhua=0&qitashixiang_qitaxuyaoshuomingdeshixiang='

    @property
    def _update_info_header(self) -> dict:
        h = {
            'Content-Type': 'application/x-www-form-urlencoded',
            'Host': 'e-report.neu.edu.cn',
            'Origin': 'https://e-report.neu.edu.cn',
        }
        if len(self._ip) > 0:
            h['X-Forwarded-For'] = self._ip
        return h

    @property
    def _info_url(self) -> str:
        return f'https://e-report.neu.edu.cn/api/profiles/{self._username}?xingming={self._name}'

    @property
    def _body_temperature(self) -> float:
        return 36 + randint(4, 7) / 10

    @property
    def _report_body_temperature_url(self) -> str:
        hour = get_current_hour()
        item_id = 1 if 7 <= hour <= 9 else 2 if 12 <= hour <= 14 else 3
        return f'https://e-report.neu.edu.cn/inspection/items/{item_id}/records'

    @property
    def _report_body_temperature_body(self) -> str:
        return f'_token={self._token}&temperature={self._body_temperature}&suspicious_respiratory_symptoms=0&symptom_descriptions='

    @staticmethod
    def _is_login_success(resp: Response) -> bool:
        return resp.url.startswith("https://e-report.neu.edu.cn")

    # property 不好看
    def _is_reported(self) -> bool:
        return self._date == time.strftime(r'%Y-%m-%d', time.localtime())

    @staticmethod
    def _unexpected_exception(error: Exception = None) -> str:
        return f'网络错误或其他错误\n{error}'

    def _login(self) -> (bool, str):
        try:
            resp: Response = self._client.get(self._init_url)
            lt: list = self._lt_matcher.findall(resp.text)
            lp: list = self._login_path_matcher.findall(resp.text)
            if len(lt) < 1 or len(lp) < 1:
                return False, self._bad_init_login
            self._lt = lt[0]
            self._login_path = lp[0]

            resp: Response = self._client.post(self._login_url, data=self._login_body, headers=self._login_header)
            if self._is_login_success(resp):
                return True, ''
            return False, self._wrong_auth
        except Exception as e:
            return False, self._unexpected_exception(e)

    def _login_service(self) -> (bool, str):
        try:
            resp: Response = self._client.get(self._service_url)
            self._token = self._token_matcher.findall(resp.text)[0]
            self._name = self._name_matcher.findall(resp.text)[0]
            return True, ''
        except Exception as e:
            return False, self._unexpected_exception(e)

    def _get_info(self) -> (bool, str):
        try:
            resp: Response = self._client.get(self._info_url)

            if resp.text.find(self._username) == -1:
                return False, self._bad_info

            date = self._date_matcher.findall(resp.text)
            klass = self._class_matcher.findall(resp.text)

            if len(date) < 1 or len(klass) < 1:
                return False, self._bad_info

            self._date = date[0]
            self._class = klass[0]

            return True, ''
        except Exception as e:
            return False, self._unexpected_exception(e)

    def _update_info(self) -> (bool, str):
        try:
            resp: Response = self._client.post(self._update_info_url, data=self._update_info_body,
                                               headers=self._update_info_header)
            if resp.status_code == 201:
                return True, ""
            return False, resp.text
        except Exception as e:
            return False, self._unexpected_exception(e)

    def _report_body_temperature(self):
        try:
            resp: Response = self._client.post(self._report_body_temperature_url,
                                               data=self._report_body_temperature_body,
                                               headers=self._update_info_header)
            print(resp.status_code)
            if resp.status_code == 200:
                return True, ""
            return False, resp.text
        except Exception as e:
            return False, self._unexpected_exception(e)

    def do(self, notifier: Notifier):
        today = time.strftime('%m/%d/%Y')

        # 登陆
        success, msg = self._login()
        if not success:
            notifier.send(f"{today} 登陆失败", msg)
            return
        # 进入平台
        success, msg = self._login_service()
        if not success:
            notifier.send(f"{today} 鉴权失败", msg)
            return
        # 获取信息
        success, msg = self._get_info()
        if not success:
            notifier.send(f"{today} 获取已有信息失败", msg)
            return
        # 是否今日有签到过
        if not self._is_reported():
            # 打卡
            success, msg = self._update_info()
            if not success:
                notifier.send(f"{today} 打卡失败", msg)
                return
            notifier.send(f"{today} 打卡成功", "I'm fine, thank you.")

        # 上报体温
        success, msg = self._report_body_temperature()
        if not success:
            notifier.send(f"{today} 上报体温失败", msg)
            return
        notifier.send(f"{today} 上报体温成功", "I'm fine, really thank you.")

"""
This file contains the Board class, which is used to represent the board in the game.

@author: Landon Moceri (with the help of GitHub Copilot)
"""
import pygame

class Board:
    def __init__(self, width, spot_size):
        self.width = width
        self.empty_color = (255, 255, 255)
        self.obstacle_color = (0, 0, 0)
        self.spot_size = spot_size

        # Create a 2D array to represent the board
        self.grid = [[' ' for _ in range(self.width)] for _ in range(self.width)]
        self.load_board()

    def load_board(self):
        # Read in the board from board.txt
        f = open("./FinalProject/board.txt", "r")
        for i in range(self.width):
            line = f.readline()
            for j in range(self.width):
                if line[j] == " ":
                    self.fill_position(i, j, 0)
                if line[j] == "-":
                    self.fill_position(i, j, 2)

    def draw(self, screen):
        # Draw the board, only the obstacles and empty spaces
        for x in range(self.width):
            for y in range(self.width):
                if self.grid[x][y] == 1:
                    pass
                elif self.grid[x][y] == 2:
                    pygame.draw.rect(screen, self.obstacle_color, (x * self.spot_size, y * self.spot_size, self.spot_size, self.spot_size))
                elif self.grid[x][y] == 3:
                    pass
                else:
                    pygame.draw.rect(screen, self.empty_color, (x * self.spot_size, y * self.spot_size, self.spot_size, self.spot_size))

    def fill_position(self, row, col, value):
        self.grid[row][col] = value

    def get_position(self, row, col):
        return self.grid[row][col]

    def reset(self):
        self.grid = [[' ' for _ in range(self.width)] for _ in range(self.width)]
        self.load_board()

# This program will generate traffic for ACME Fitness Shop App. It simulates both Authenticated and Guest user scenarios. You can run this program either from Command line or from
# the web based UI. Refer to the "locust" documentation for further information. 
from time import sleep
from locust import HttpUser, task, SequentialTaskSet, between
import random
import logging

# List of users (pre-loaded into ACME Fitness shop)
users = ["eric", "phoebe", "dwight", "han", "elaine", "walter"]

# GuestUserBrowsing simulates traffic for a Guest User (Not logged in)
class UserBrowsing(SequentialTaskSet):
    def on_start(self):
        self.getProducts()
    def listCatalogItems(self):
        products = []
        response = self.client.get("/products")
        if response.ok:
            items = response.json()["data"]
            for item in items:
                products.append(item["id"])
        return products
    def getProductDetails(self, id):
        """Get details of a specific product"""
        details = {}
        response = self.client.get("/products/"+id)
        if response.ok:
            details = response.json()["data"]
            logging.debug("getProductDetails: " + str(details))
        return details
    def getProductImages(self,id):
        """Gets all three image URLs for a product"""
        details = self.getProductDetails(id)
        if details:
            for x in range(1, 4):
                self.client.get(details["imageUrl"+str(x)])
    def getProductName(self, id):
        name = ""
        details = self.getProductDetails(id)
        if details:
            name = details["name"]
        logging.debug("NAME: "+name+ " for id: "+id)
        return name

    @task
    def getProducts(self):
        logging.debug("User - Get Products")
        self.client.get("/products")
    @task(2)
    def getProduct(self):
        """Get details of a specific product"""
        logging.debug("User - Get a product")
        products = self.listCatalogItems()
        id = random.choice(products)
        response = self.client.get("/products/"+ id)
        if response.ok:
            product = response.json()
            logging.debug("Product info - " +  str(product))
    @task
    def getImages(self):
        """Get images of a random product"""
        logging.debug("User - Get images of random product")
        products = self.listCatalogItems()
        id = random.choice(products)
        self.getProductImages(id)
    @task(2)
    def index(self):
        self.client.get("/")

